// 完整人物来源先于本段全史；原Task、实交与取消表保持唯一。新尾只给选中的私人Offer增加回程要求。
#include "task_message_return_world.hpp"
#include "task_message_return_control.hpp"
#include "resident/kernel/world_bundle.hpp"
#include "resident/domains/military/military_roster_history.hpp"
namespace hanmo::resident {namespace {
const TaskMessageReturnState* state(const WorldBundle& w){return w.tasks.message_returns?&*w.tasks.message_returns:nullptr;}
Status ready(const WorldBundle& w){if(!w.dynamic_enabled()||!w.catalog->task_message_returns||!w.catalog->common||!w.catalog->tasks||!w.catalog->interaction||!w.family_life_enabled()||!w.catalog->task_message_handoffs_enabled||w.catalog->task_message_handoff_version!=2||!w.catalog->task_static_assets_enabled||!w.tasks.message_handoffs||w.tasks.message_handoffs->version!=2||!w.tasks.static_assets||!state(w))return common_failure("TaskMessageReturnProfileRequired");return validate_task_message_return_extension_pair(*w.catalog->task_message_returns,w.catalog->task_extensions.get());}
TaskMessageReturnSources sources(const WorldBundle& w,const DynamicStepInput* phase){return {w.common,*w.catalog->common,w.tasks,*w.catalog->tasks,*w.tasks.message_handoffs,*w.tasks.static_assets,*w.catalog->interaction,*w.catalog->task_message_returns,*state(w),phase,[&w,phase](const StableId& actor,Integer tick,const StableId& fact){FamilyDeathOriginRead deaths=[&w,phase](const StableId& who)->Outcome<std::optional<FamilyDeathOrigin>>{auto result=phase?query_military_actor_death(w.common,w.military,who,*phase):query_military_actor_death(w.common,w.military,who);if(!result.ok)return {false,{},result.error};if(!result.value)return {true,std::nullopt,{}};const auto& d=*result.value;return {true,FamilyDeathOrigin{d.actor_id,d.casualty_fact_id,d.battle_id,d.tick},{}};};return read_actor_presence_before_fact(w.common,*w.catalog->common,deaths,actor,tick,fact,phase);},w.dynamic_enabled()&&w.catalog->director&&w.catalog->director->dynamic_subjects?TaskMessageReturnSubmitterMode::controlled_player:TaskMessageReturnSubmitterMode::legacy_actor,[&w,phase](Integer tick,const StableId& fact){return task_message_return_player_before(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact,phase);}};}
}
TaskMessageReturnWorldAccess::TaskMessageReturnWorldAccess(const WorldBundle& w,const DynamicStepInput* phase):interaction_access_(w.services.interaction_access()),services_{sources(w,phase),w.interaction,interaction_access_}{}
Outcome<std::shared_ptr<TaskMessageReturnWorldAccess>> TaskMessageReturnWorldAccess::create(const WorldBundle& w,const DynamicStepInput* phase){if(!w.catalog->task_message_returns){if(state(w))return {false,{},common_failure("TaskMessageReturnProfileMismatch").error};return {true,nullptr,{}};}auto valid=ready(w);if(!valid.ok)return {false,{},valid.error};return {true,std::shared_ptr<TaskMessageReturnWorldAccess>(new TaskMessageReturnWorldAccess(w,phase)),{}};}
Status validate_task_message_return_world(const WorldBundle& w){auto valid=validate_task_message_return_layout(w.common,w.catalog->identity.module_versions,state(w));if(!valid.ok)return valid;if(bool(w.catalog->task_message_returns)!=bool(state(w)))return common_failure("TaskMessageReturnProfileMismatch");if(!state(w))return common_success();valid=ready(w);if(!valid.ok)return valid;return validate_task_message_returns(sources(w,nullptr));}
Status task_message_return_npc_command_allowed(const WorldBundle& w,const StableId& kind,const TaskCommand* task){if(kind==task_message_return_collect_command)return common_failure("TaskMessageReturnOuterResultRequired");if(w.catalog->task_message_returns&&task&&task->kind=="report_offer"&&task_message_return_policy(*w.catalog->task_message_returns,task_command_offer(*task).id))return common_failure("TaskMessageReturnOuterResultRequired");return common_success();}
Outcome<TaskMessageReturnQuote> preview_task_message_return_world(const WorldBundle& w,const StableId& actor,const TaskMessageReturnCollect& command){auto valid=ready(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return preview_task_message_return_collection(sources(w,nullptr),w.interaction,access,actor,command);}
Outcome<StableId> commit_task_message_return_world(WorldBundle& w,const StableId& actor,const TaskMessageReturnCollect& command,const TaskMessageReturnQuote& quote){if(command.task_id!=quote.task_id||quote.declaration.meeting.actor_id!=actor)return {false,{},common_failure("TaskMessageReturnQuoteMismatch").error};auto holder=TaskMessageReturnWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("TaskMessageReturnProfileRequired").error};const auto& x=holder.value->services();auto current=preview_task_message_return_collection(x.sources,w.interaction,x.interaction_access,actor,command);if(!current.ok)return {false,{},current.error};return begin_task_message_return_collection_in_candidate(w.common,*w.tasks.message_returns,x.sources,w.interaction,x.interaction_access,quote);}
Outcome<TaskEffect> finish_task_message_return_world(WorldBundle& w,const StableId& action,const DynamicStepInput& phase){auto holder=TaskMessageReturnWorldAccess::create(w,&phase);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("TaskMessageReturnProfileRequired").error};const auto& x=holder.value->services();return finish_task_message_return_collection_in_candidate(w.common,*w.tasks.message_returns,x.sources,w.interaction,x.interaction_access,action,phase);}
Outcome<BoundaryValue> query_task_message_returns_world(const WorldBundle& w,Integer cursor){if(!w.catalog->task_message_returns)return {true,boundary::obj({{"ok",BoundaryValue{true}},{"enabled",BoundaryValue{false}}}),{}};auto valid=ready(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return query_task_message_returns(sources(w,nullptr),w.interaction,access,cursor);}
Outcome<TaskMessageReturnResultBatch> task_message_return_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){if(!after.catalog->task_message_returns){if(before.catalog->task_message_returns||state(before)||state(after))return {false,{},common_failure("TaskMessageReturnProfileMismatch").error};return {true,{before.common.tick(),{}},{}};}auto valid=ready(before);if(!valid.ok)return {false,{},valid.error};valid=ready(after);if(!valid.ok)return {false,{},valid.error};auto fresh=task_message_return_new_result_sources(*state(before),*state(after),actor,kind,details,after.common.tick(),before.common.tick());if(!fresh.ok)return {false,{},fresh.error};return {true,{before.common.tick(),std::move(fresh.value)},{}};}
Status bind_task_message_return_result_world(WorldBundle& w,const TaskMessageReturnResultBatch& batch,const StableId& actor,Integer request,const CommitResult& result){if(!w.catalog->task_message_returns)return batch.facts.empty()?common_success():common_failure("TaskMessageReturnProfileRequired");auto valid=ready(w);if(!valid.ok)return valid;return bind_task_message_return_results(w.common,*w.tasks.message_returns,sources(w,nullptr),batch.facts,actor,request,result,batch.before_tick);}
}
